def integrate_with_singularity(func, a, b, c):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.qc25c.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int)]
    gsl.qc25c.restype = None

    params = (func,)
    gsl_func = GSLFunction()
    gsl_func.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(wrapper, params)

    result = ctypes.c_double(0.0)
    abs_err = ctypes.c_double(0.0)
    reliability = ctypes.c_int(0)

    gsl.qc25c(ctypes.cast(gsl_func.f, ctypes.c_void_p), a, b, c, 1000, 1000, ctypes.byref(result), ctypes.byref(abs_err), ctypes.byref(reliability))

    return (float(result.value), float(abs_err.value), int(reliability.value))

