import sys

class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = ctypes.POINTER(ctypes.c_double)()
        self.rows = rows
        self.cols = cols
        self._alloc()

    def _alloc(self):
        self.matrix = ctypes.c_void_p(ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_alloc(self.rows, self.cols))

    def _free(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_free(self.matrix)

    def set_data(self, data):
        for i in range(self.rows):
            for j in range(self.cols):
                ctypes.c_double.in_dll(self.matrix, f"{i}_{j}").value = data[i, j]

    def get_data(self):
        data = np.zeros((self.rows, self.cols), dtype=np.float64)
        for i in range(self.rows):
            for j in range(self.cols):
                data[i, j] = ctypes.c_double.in_dll(self.matrix, f"{i}_{j}").value
        return data

    def __del__(self):
        self._free()

def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray) or not np.issubdtype(np_array.dtype, np.floating):
        raise ValueError("Input must be a numpy array of floating point type.")
    if np_array.ndim != 2:
        raise ValueError("Input must be a 2D numpy array.")
    gsl_matrix = GSLMatrix(np_array.shape[0], np_array.shape[1])
    gsl_matrix.set_data(np_array)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    return gsl_matrix.get_data()

def gsl_multifit_covar(jacobian, epsrel):
    if not isinstance(jacobian, GSLMatrix):
        raise ValueError("First argument must be a GSLMatrix instance.")
    if not isinstance(epsrel, (int, float)) or epsrel <= 0:
        raise ValueError("Second argument must be a positive float.")
    cov = GSLMatrix(jacobian.rows, jacobian.cols)
    status = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_multifit_covar(
        jacobian.matrix, ctypes.c_double(epsrel), cov.matrix)
    if status != 0:
        raise RuntimeError(f"GSL error: {status}")
    return cov

